package owl.admin;
import com.sun.net.httpserver.*;import com.google.gson.*;import java.net.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import java.util.*;import java.util.concurrent.*;
/** Two distinct loopback listeners: the tunnel can reach only the collector. */
public final class AdminServer {
 static final Gson JSON=new Gson();static final SecureRandom RANDOM=new SecureRandom();
 static final Map<String,Report> REPORTS=new HashMap<>();static final Map<String,Long> SESSIONS=new HashMap<>();
 static String collector,boot,device,deviceHash;static byte[] salt,hash;static long nextLogin;static int failures;static boolean bootUsed;
 static class Report{String username;long seen;Report(String n,long t){username=n;seen=t;}}
 static String random(){byte[] b=new byte[32];RANDOM.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 static byte[] derive(String password,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(password.toCharArray(),salt,600000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
 static boolean equal(String a,String b){return a!=null&&b!=null&&MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}
 static void reply(HttpExchange x,int code,String type,String text)throws Exception{byte[] b=text.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type",type+"; charset=utf-8");x.getResponseHeaders().set("Cache-Control","no-store");x.getResponseHeaders().set("X-Content-Type-Options","nosniff");x.getResponseHeaders().set("Referrer-Policy","no-referrer");x.getResponseHeaders().set("Content-Security-Policy","default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; frame-ancestors 'none'; connect-src 'self'");x.sendResponseHeaders(code,b.length);try(java.io.OutputStream o=x.getResponseBody()){o.write(b);}}
 static JsonObject body(HttpExchange x)throws Exception{byte[] b=x.getRequestBody().readNBytes(2049);if(b.length>2048)throw new IllegalArgumentException();return new JsonParser().parse(new String(b,StandardCharsets.UTF_8)).getAsJsonObject();}
 static String value(JsonObject j,String key){return j.has(key)&&!j.get(key).isJsonNull()?j.get(key).getAsString():"";}
 static synchronized void collect(HttpExchange x)throws Exception{
  if(!"/heartbeat".equals(x.getRequestURI().getPath())||!"POST".equals(x.getRequestMethod())){reply(x,404,"text/plain","Not found");return;}
  if(!equal(collector,x.getRequestHeaders().getFirst("X-Turbo-Key"))){reply(x,403,"text/plain","Denied");return;}
  JsonObject data=body(x);String id=value(data,"session"),name=value(data,"username");if(!id.matches("[a-f0-9-]{36}")||name.length()>64||name.matches(".*[\\p{Cntrl}<>].*")){reply(x,400,"text/plain","Invalid report");return;}
  expire();if(REPORTS.size()>=10000&&!REPORTS.containsKey(id)){reply(x,503,"text/plain","Capacity reached");return;}
  if(data.has("leave")&&data.get("leave").getAsBoolean())REPORTS.remove(id);else REPORTS.put(id,new Report(name,System.nanoTime()));reply(x,200,"application/json","{\"ok\":true}");
 }
 static void expire(){long now=System.nanoTime();REPORTS.values().removeIf(r->now-r.seen>120_000_000_000L);SESSIONS.values().removeIf(t->now-t>900_000_000_000L);}
 static boolean authenticated(HttpExchange x){String cookies=x.getRequestHeaders().getFirst("Cookie");if(cookies==null)return false;for(String cookie:cookies.split(";")){String[] p=cookie.trim().split("=",2);if(p.length==2&&p[0].equals("turbo_admin")&&SESSIONS.containsKey(p[1]))return true;}return false;}
 static synchronized void admin(HttpExchange x)throws Exception{
  if(!"127.0.0.1:8764".equals(x.getRequestHeaders().getFirst("Host"))){reply(x,403,"text/plain","Denied");return;}expire();String path=x.getRequestURI().getPath();
  if((path.equals("/launch")||path.equals("/shutdown"))&&x.getRequestMethod().equals("POST")){String credential=x.getRequestHeaders().getFirst("X-Turbo-Device");if(x.getRequestHeaders().getFirst("Origin")!=null||credential==null||!equal(deviceHash,Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(credential.getBytes(StandardCharsets.UTF_8))))){reply(x,403,"text/plain","Denied");return;}if(path.equals("/shutdown")){reply(x,200,"text/plain","Stopping");new Thread(()->System.exit(0)).start();return;}boot=random();bootUsed=false;reply(x,200,"text/plain","http://127.0.0.1:8764/device?key="+boot);return;}
  if(path.equals("/device")&&x.getRequestMethod().equals("GET")){String query=x.getRequestURI().getRawQuery();if(!bootUsed&&equal("key="+boot,query)){bootUsed=true;device=random();x.getResponseHeaders().add("Set-Cookie","turbo_device="+device+"; HttpOnly; SameSite=Strict; Path=/");x.getResponseHeaders().set("Location","/");x.sendResponseHeaders(303,-1);x.close();return;}reply(x,403,"text/plain","Open the panel using Turbo Admin.cmd on your PC.");return;}
  String cookies=x.getRequestHeaders().getFirst("Cookie");boolean trusted=false;if(cookies!=null&&device!=null)for(String cookie:cookies.split(";"))if(equal(cookie.trim(),"turbo_device="+device))trusted=true;
  if(!trusted){reply(x,403,"text/plain","Launch Turbo Admin.cmd on the administrator PC.");return;}
  if(path.equals("/login")&&x.getRequestMethod().equals("POST")){
   if(!"http://127.0.0.1:8764".equals(x.getRequestHeaders().getFirst("Origin"))){reply(x,403,"text/plain","Denied");return;}
   if(System.nanoTime()<nextLogin){reply(x,429,"text/plain","Wait before trying again.");return;}JsonObject data=body(x);if(!MessageDigest.isEqual(hash,derive(value(data,"password"),salt))){failures++;nextLogin=System.nanoTime()+Math.min(60,failures*2)*1_000_000_000L;reply(x,403,"text/plain","Incorrect password.");return;}
   failures=0;String session=random();SESSIONS.put(session,System.nanoTime());x.getResponseHeaders().add("Set-Cookie","turbo_admin="+session+"; HttpOnly; SameSite=Strict; Path=/");reply(x,200,"application/json","{\"ok\":true}");return;
  }
  if(path.equals("/stats")){if(!authenticated(x)){reply(x,401,"text/plain","Log in");return;}List<String> names=new ArrayList<>();for(Report r:REPORTS.values())if(!r.username.isEmpty())names.add(r.username);Collections.sort(names);JsonObject data=new JsonObject();data.addProperty("active",REPORTS.size());data.add("usernames",JSON.toJsonTree(names));reply(x,200,"application/json",JSON.toJson(data));return;}
  if(!path.equals("/")){reply(x,404,"text/plain","Not found");return;}reply(x,200,"text/html",PAGE);
 }
 static final String PAGE="<!doctype html><html><meta charset='utf-8'><title>Turbo Admin</title><style>body{background:#171b21;color:#eee;font:17px system-ui;max-width:760px;margin:70px auto}input,button{font:inherit;padding:12px;background:#292f38;color:white;border:1px solid #626b79;border-radius:7px}li{padding:6px}small{color:#aab4c2}</style><h1>Turbo Client · Admin</h1><p>Active, opted-in app sessions in the last 2 minutes.</p><form id='login'><input id='password' type='password' autocomplete='current-password' placeholder='Admin password' required><button>Log in</button></form><p id='status'></p><section id='data' hidden><h2 id='count'></h2><p>Usernames shared with permission:</p><ul id='names'></ul><small>Counts represent sessions, not unique people. Reports are held only in memory. No IP addresses are stored.</small></section><script>const status=document.getElementById('status');async function refresh(){const r=await fetch('/stats');if(!r.ok){document.getElementById('login').hidden=false;document.getElementById('data').hidden=true;return;}const d=await r.json();document.getElementById('login').hidden=true;document.getElementById('data').hidden=false;document.getElementById('count').textContent=d.active+' active sessions';const n=document.getElementById('names');n.replaceChildren();for(const name of d.usernames){const li=document.createElement('li');li.textContent=name;n.appendChild(li)}}document.getElementById('login').onsubmit=async e=>{e.preventDefault();const p=document.getElementById('password');const r=await fetch('/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:p.value})});p.value='';status.textContent=r.ok?'':await r.text();if(r.ok)refresh()};setInterval(refresh,10000);refresh();</script></html>";
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]);Files.createDirectories(root);Path config=root.resolve("admin-config.json");
  if(args.length>1&&args[1].equals("--init")){String password=new java.io.BufferedReader(new java.io.InputStreamReader(System.in,StandardCharsets.UTF_8)).readLine();if(Files.exists(config))throw new IllegalStateException("Already configured");byte[] salt=new byte[32];RANDOM.nextBytes(salt);JsonObject j=new JsonObject();j.addProperty("salt",Base64.getEncoder().encodeToString(salt));j.addProperty("passwordHash",Base64.getEncoder().encodeToString(derive(password,salt)));j.addProperty("collectorToken",random());Files.writeString(config,JSON.toJson(j));return;}
  JsonObject c=new JsonParser().parse(Files.readString(config)).getAsJsonObject();salt=Base64.getDecoder().decode(c.get("salt").getAsString());hash=Base64.getDecoder().decode(c.get("passwordHash").getAsString());collector=c.get("collectorToken").getAsString();
  // The launch script must decrypt its Windows-user/PC-bound DPAPI credential.
  String key=new java.io.BufferedReader(new java.io.InputStreamReader(System.in,StandardCharsets.UTF_8)).readLine();String expected=c.get("deviceKeyHash").getAsString();deviceHash=expected;if(key==null||!equal(expected,Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8)))))throw new SecurityException("Device authentication failed");
  boot=random();HttpServer publicServer=HttpServer.create(new InetSocketAddress("127.0.0.1",8765),32),adminServer=HttpServer.create(new InetSocketAddress("127.0.0.1",8764),8);ExecutorService pool=Executors.newFixedThreadPool(8,r->{Thread t=new Thread(r,"turbo-admin");t.setDaemon(true);return t;});publicServer.setExecutor(pool);adminServer.setExecutor(pool);
  publicServer.createContext("/",x->{try{collect(x);}catch(Exception e){try{reply(x,400,"text/plain","Invalid request");}catch(Exception ignored){x.close();}}});adminServer.createContext("/",x->{try{admin(x);}catch(Exception e){try{reply(x,400,"text/plain","Invalid request");}catch(Exception ignored){x.close();}}});publicServer.start();adminServer.start();Runtime.getRuntime().addShutdownHook(new Thread(()->{publicServer.stop(0);adminServer.stop(0);pool.shutdownNow();synchronized(AdminServer.class){REPORTS.clear();SESSIONS.clear();}}));System.out.println("ADMIN_URL=http://127.0.0.1:8764/device?key="+boot);
 }
}
